mapper.update:
UPDATE resource_entity
SET delete_flag = id, deleted_at = #{deletedAt}
WHERE id IN

    #{id}

AND delete_flag = 0 AND tenant_id = #{tenantId}

mapper.select:
WITH RECURSIVE ancestors AS ( SELECT id, parent_id, id as original_id FROM resource_entity WHERE id IN
#{id}
AND tenant_id = #{tenantId} AND delete_flag = 0 UNION ALL SELECT r.id, r.parent_id, a.original_id FROM resource_entity r INNER JOIN ancestors a ON r.id = a.parent_id WHERE r.tenant_id = #{tenantId} AND r.delete_flag = 0 ) SELECT original_id as resourceId, parent_id as ancestorId FROM ancestors WHERE parent_id IS NOT NULL

WITH RECURSIVE descendants AS ( SELECT id, parent_id, id as original_id FROM resource_entity WHERE id IN
#{id}
AND tenant_id = #{tenantId} AND delete_flag = 0 UNION ALL SELECT r.id, r.parent_id, d.original_id FROM resource_entity r INNER JOIN descendants d ON r.parent_id = d.id WHERE r.tenant_id = #{tenantId} AND r.delete_flag = 0 ) SELECT original_id as resourceId, id as descendantId FROM descendants WHERE id != original_id
